/** The command: `trace`, `summary`, and `dead`, each over the log on standard input, under an optional policy file. */

import { readFileSync } from 'node:fs'
import { LogError, parse, parsePolicy, splitLines } from './parse.js'
import { run } from './queue.js'

const USAGE = 'usage: cli.js trace|summary|dead [<policy>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
const policyPath = argv[1]
if (!['trace', 'summary', 'dead'].includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

const policy = {}
if (policyPath !== undefined) {
  let text
  try {
    text = readFileSync(policyPath, 'utf8')
  } catch {
    fail(`cannot read policy ${policyPath}`)
  }
  try {
    parsePolicy(splitLines(text), policy)
  } catch (error) {
    if (!(error instanceof LogError)) throw error
    fail(`${policyPath}: line ${error.line}: ${error.message}`)
  }
}

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), policy)
} catch (error) {
  if (!(error instanceof LogError)) throw error
  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
}

const { attempts, end, deadLetters } = run(parsed.jobs, parsed.submissions, policy)
const out = []
if (mode === 'trace') {
  for (const one of attempts) out.push(`${one.start} ${one.id} attempt=${one.attempt} ${one.outcome} finish=${one.finish}`)
  out.push(`end ${end}`)
} else if (mode === 'summary') {
  const deadIds = new Set(deadLetters.map(({ id }) => id))
  for (const { id } of [...parsed.submissions].sort((left, right) => (left.id < right.id ? -1 : 1))) {
    const own = attempts.filter(one => one.id === id)
    const outcome = deadIds.has(id) ? 'dead' : own[own.length - 1].outcome
    out.push(`${id} attempts=${own.length} ${outcome}`)
  }
  out.push(`end ${end}`)
} else {
  for (const { id, attempts: n, at } of deadLetters) out.push(`${id} attempts=${n} at=${at}`)
  out.push(`total ${deadLetters.length}`)
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

